 rows.append({'source_id':sid,'level':level,'parameters':p,'prompt':q[':question/problem'],'worked_solution':q[':question/worked-solution'],'fields':fs,'plot':'one point-only Cartesian grid in prompt; no line drawn','stage_sequence':['coordinate readback','state substitution criterion','A equation / substituted coordinates / evaluated equality with truth marker / conclusion','B same stages','C same stages','final exact matching subset']if level!='unrated'else['coordinate readback','only B satisfies equation'],'template':'source-easy'if level=='easy'else'source-moderate'if level=='moderate'else'unrated-'+sid,'complete_profile':'easy five subsets AC,A,B,C,BC'if level=='easy'else'moderate five subsets AC,C,AB,B,A'if level=='moderate'else'three independent checkbox Boolean fields'})
